{
  "services": [
    {
      "name": "banner",
      "description": "Long-lived service that announces a URL",
      "kind": "local",
      "command": "%%NODE%%",
      "args": [
        "%%WORKSPACE%%/banner.js"
      ],
      "cwd": "%%WORKSPACE%%",
      "envKeys": [
        "PARITY_MODE"
      ]
    },
    {
      "name": "quitter",
      "description": "Exits with a known non-zero code",
      "kind": "local",
      "command": "%%NODE%%",
      "args": [
        "%%WORKSPACE%%/quitter.js"
      ],
      "cwd": "%%WORKSPACE%%"
    },
    {
      "name": "idle",
      "description": "Registered but never started",
      "kind": "local",
      "command": "%%NODE%%",
      "args": [
        "%%WORKSPACE%%/banner.js"
      ],
      "cwd": "%%WORKSPACE%%"
    },
    {
      "name": "remote",
      "kind": "ssh",
      "host": "parity-host",
      "cwd": "/srv/app",
      "command": "npm start",
      "envKeys": [
        "A_FIRST",
        "Z_LAST"
      ]
    },
    {
      "name": "composed",
      "kind": "docker-compose",
      "cwd": "%%WORKSPACE%%",
      "composeFile": "compose.yml",
      "composeService": "web"
    }
  ],
  "bundles": [
    {
      "name": "pair",
      "services": [
        "banner",
        "quitter"
      ]
    },
    {
      "name": "missing",
      "services": [
        "banner",
        "not-registered"
      ]
    }
  ]
}

